 S('aliases',"SELECT n.__path,n.__start,CASE WHEN n.kind='aliased_import' THEN n.alias_source WHEN parent.kind='import_statement' THEN rx_extract(n.text,'^([\\w]+)',1) ELSE n.text END AS local,CASE WHEN parent.kind='import_from_statement' THEN trim(parent.module_name_source,'.')||'.'||CASE WHEN n.kind='aliased_import' THEN n.name_source ELSE n.text END ELSE CASE WHEN n.kind='aliased_import' THEN n.name_source ELSE n.text END END AS origin FROM nodes n JOIN nodes parent ON parent.__path=n.__path AND parent.id=n.parent WHERE parent.kind IN ('import_statement','import_from_statement') AND n.kind IN ('dotted_name','aliased_import') AND n.__start!=coalesce(parent.module_name_start,-1)",('__path','local','__start')),
 S('conditional_classes',"WITH latest AS MATERIALIZED (SELECT __path,name,max(__start) AS __start FROM classes GROUP BY __path,name) SELECT c.*,module.qualified||'.'||c.name AS qualified_name,1 AS chosen FROM latest w JOIN classes c ON c.__path=w.__path AND c.name=w.name AND c.__start=w.__start JOIN module_names module ON module.__path=c.__path",('__path','id'),('qualified_name',)),
